@php($items = $categories->take(min(24, max(1, (int)($settings['limit'] ?? 12)))))
@if($items->isNotEmpty())<section class="theme-archive-categories theme-container" data-theme-block="archive_category_navigation"><h2>{{ $settings['title'] ?? 'دسته‌بندی‌ها' }}</h2><div class="theme-grid theme-category-grid">@foreach($items as $category)<a href="{{ route('product-categories.show', $category) }}">@if(($settings['show_image'] ?? true) && $category->logo_url)<img src="{{ $category->logo_url }}" alt="{{ $category->name }}" loading="lazy">@endif<strong>{{ $category->name }}</strong>@if($settings['show_count'] ?? true)<small>{{ $category->products_count }} محصول</small>@endif</a>@endforeach</div></section>@endif
